/** SC/v1/Board/SC26_0027 Memorial Day Sale/hero-desktop -- generated by the template lab from Figma node 569:2491
 *  (SC/v1/Board/SC26_0027 Memorial Day Sale/hero-desktop). Everything is drawn from the board itself
 *  (FigmaLayers); the slots below are what a designer edits, each in its
 *  board place and stacking order:
 *    copy tied to the brief -- offer, lead, title, cta;
 *    board copy, editable -- none;
 *    photos -- photo; brand slots -- none.
 *  Text contracts come from each board layer (boardFit). NUDGE (./nudges.ts)
 *  holds the fix loop's per-layer corrections to Figma's render. */
import type { SheetAsset } from '../../../../../sheet/types';
import { Ground } from '../../../../../edit/Editable';
import { Picture } from '../../../../../edit/Picture';
import { ZONE_LIST, photoFor } from '../../../../../model/compose';
import { FigmaLayers, FigmaText, FigmaMark, type Slot } from '../../../../../render/figma/FigmaLayers';
import { cropOf, type FigmaLayout } from '../../../../../render/figma/layout';
import board from './layout.json';
import { NUDGE } from './nudges';

/** The brief's sale name for the board's own ("Memorial Day"), in the line that
 *  says it: the whole name where the line says "SALE" too, else without it
 *  ("MEMORIAL DAY" over "SALE"); the rest of the line kept ("… FAVORITES");
 *  capitals where the board's are. */
const SALE_NAME = /\bMemorial\s+Day(\s+sale)?\b/i;
const named = (title: string, board: string) => board.replace(SALE_NAME, (said, sale) => {
  const t = sale ? title : title.replace(/\s*sale\s*$/i, '');
  return said === said.toUpperCase() ? t.toUpperCase() : t;
});

/** Which board layer each editable layer is, by the part of its id after the asset's. */
export const HERO_DESKTOP_569_2491_FIGMA = {
  "offer": "538:37563", // offer: 60% OFF
  "lead": "538:37564", // lead: UP\u2028TO
  "title": "538:37567", // title: MEMORIAL DAY SALE
  "cta": "538:37572", // cta: Shop Now
  "art/vector-741": "538:37561", // graphic: Vector 741
  "arrow/arrow": "538:37569", // graphic: Group 3191
} as const;

export function HeroDesktop_569_2491({ asset }: { asset: SheetAsset }) {
  const layout = board as unknown as FigmaLayout, id = asset.id;
  const zone = ZONE_LIST.find(z => z.id === asset.media.photo) ?? photoFor('hike', 0);
  const slots: Record<string, Slot> = {
    [HERO_DESKTOP_569_2491_FIGMA["offer"]]: (l, box, n) => <FigmaText l={l} box={box} nudge={n} id={`${id}/offer`} contract="lab.offer" layout={layout}
      text={asset.copy.offer || l.text!.chars} />,
    [HERO_DESKTOP_569_2491_FIGMA["lead"]]: (l, box, n) => <FigmaText l={l} box={box} nudge={n} id={`${id}/lead`} contract="lab.lead" layout={layout}
      text={asset.copy.lead ? (l.text!.chars.includes('\u2028') ? asset.copy.lead.replace(/\s+/, '\n') : asset.copy.lead) : l.text!.chars} />,
    [HERO_DESKTOP_569_2491_FIGMA["title"]]: (l, box, n) => <FigmaText l={l} box={box} nudge={n} id={`${id}/title`} contract="lab.title" layout={layout}
      text={asset.copy.title ? named(asset.copy.title, l.text!.chars) : l.text!.chars} />,
    [HERO_DESKTOP_569_2491_FIGMA["cta"]]: (l, box, n) => <FigmaText l={l} box={box} nudge={n} id={`${id}/cta`} contract="lab.cta" layout={layout}
      text={asset.copy.cta || l.text!.chars} />,
    [HERO_DESKTOP_569_2491_FIGMA["art/vector-741"]]: (l, box) => <FigmaMark l={l} box={box} id={`${id}/art/vector-741/mark`} src="/graphics/named-sale-vector-741-m7ydr5.svg"
      fill="#F14222" layout={layout} />,
    [HERO_DESKTOP_569_2491_FIGMA["arrow/arrow"]]: (l, box) => <FigmaMark l={l} box={box} id={`${id}/arrow/arrow/mark`} src="/graphics/bump2-arrow.svg"
      fill="#FFFFFF" pad={[0.05707738777210708, 0.08684627575277339]} layout={layout} />,
  };
  const [w, h] = layout.size;
  // The frame's own photo, swappable, under every layer (and not drawn again by FigmaLayers).
  const photo = layout.frame.images?.[0] && layout.assets?.[layout.frame.images[0].ref];
  const crop = photo && layout.frame.crop ? cropOf(layout.frame.crop, [w, h], [photo.w, photo.h]) : undefined;
  const drawn = { ...layout, frame: { ...layout.frame, paints: layout.frame.paints?.filter(p => p.type !== 'IMAGE') } };
  // data-figma-compiled: the studio's Figma export reads a compiled board's way (toLayers).
  return <Ground id={`${id}/fill`} className="sheet" data-figma-compiled="" style={{ width: w, height: h, position: 'relative', overflow: 'hidden', background: '#fff' }}>
    <Picture id={`${id}/photo`} zone={zone} initialSrc={photo?.src} slot focus={crop?.focus}
      initialScale={crop?.initialScale} initialRotate={crop?.rotate} initialCrop={layout.frame.crop}
      style={{ position: 'absolute', inset: 0 }} />
    <FigmaLayers layout={drawn} slots={slots} nudges={NUDGE} />
  </Ground>;
}
